const APPLICATION_PROMPT = 'Trace energy from sunlight to a cell doing work. Where does the form of energy change, and what molecule transfers it to cellular processes?';

function freezeReflections(notes, application) {
  return Object.freeze({
    notes: Object.freeze(notes.map(note => Object.freeze({...note}))),
